@dataclass(frozen=True, kw_only=True)
class SelfHeal(Model):
    """Hand-back's owning process (§3.8): a handed-back item loses conductor eligibility, gains a
    self-heal assignment, carries the worker's account of why, and awaits host-access work under
    the self-heal contract, with re-alerting at 24h dwell.
    """

    SCHEMA_ID: ClassVar[str | None] = "https://sortyard.ai/spec/self-heal.schema.json"
    STORE: ClassVar[str | None] = "state"
    id: str
    workspace_id: str
    created_at: str | None = None
    updated_at: str | None = None
