    source: Literal["git", "db"] | None = None
    #: Built-ins: feature, incident, release, support (saas-product); change, drift, incident
    #: (infrastructure); job; design-first.
    name: str
    archetype_id: str | None = None
    requires_design_ref: bool | None = None
